const fest=(n,key)=>{if(typeof c4_fs==='function')c4_fs(n,key);else S.flags.festivalScore=Math.min(10,(S.flags.festivalScore||0)+n)};
STORY.push(
/* W5 · boil-water notice */
{id:'p1_water',when:AT(5,6,1),run:()=>{MEET('p1_hollis');return {title:t('煮沸饮水通知','Boil-water notice','Aviso para ferver a água'),meta:t('第 5 周 · 主街','Week 5 · Main Street','Semana 5 · Rua principal'),text:[
 t('早上主街的水管爆了，水柱冲到邮局的屋檐那么高。镇上发了通知：三天内饮用水必须煮沸。邓巴五金店门口排起长队，霍利斯一个人在卖桶装水。','A water main blew on Main Street this morning, spraying as high as the post office eaves. The town issues a notice: boil all drinking water for three days. A line forms outside Dunbar Hardware, where Hollis is selling jugs of water by himself.','De manhã rebentou uma conduta na rua principal; o jato chegou ao beiral dos correios. A vila emite um aviso: ferver a água de beber durante três dias. Forma-se uma fila à porta da loja de ferragens Dunbar, onde o Hollis vende garrafões de água sozinho.'),
 t('队伍里有人小声说：“肯定又是罐头厂那边的老管子。”厄尔哼了一声：“什么都怪罐头厂，下雨也怪罐头厂。”','Somebody in line mutters, "Bet it\'s those old pipes over by the cannery again." Earl snorts. "Y\'all blame the cannery for everything. Blame it for the rain, too."','Alguém na fila murmura: «Aposto que são outra vez os canos velhos do lado da fábrica.» O Earl bufa. «Vocês culpam a fábrica de tudo. Até da chuva.»')],choices:[
 {t:t('煮一大锅咖啡，免费给排队的人','Boil a big pot of coffee and hand it out free to the line','Fazer um bule enorme de café e dá-lo de graça à fila'),fx:()=>{S.cash-=20;S.wk.spend+=20;S.rep+=3;addLike('p1_hollis',1);addTrust('p1_hollis',1)},next:()=>say('',t('霍利斯接过一杯，喝了一口，皱眉：“这是咖啡还是柏油？”然后又要了一杯。','Hollis takes a cup, sips, frowns. "Is this coffee or road tar?" Then asks for another.','O Hollis aceita um copo, prova, franze a testa. «Isto é café ou alcatrão?» Depois pede outro.'),t('口碑 +3 · −$20','Reputation +3 · −$20','Reputação +3 · −$20'))},
 {t:t('只上不用水的烤菜','Serve only grilled dishes that need no water','Servir só grelhados que não precisam de água'),req:()=>S.stats.oficio>=25||NEED(t('手艺 25','Craft 25','Ofício 25')),fx:()=>{S.cash+=50;S.wk.rev+=50;stat('oficio',1)},next:()=>say('',t('三天里你只开烤架，盘子用纸的。生意比平时还好——全镇的厨房都停了。','For three days it\'s grill only, on paper plates. Business beats a normal week; every kitchen in town is down.','Durante três dias, só grelha e pratos de papel. O negócio corre melhor do que o normal — todas as cozinhas da vila estão paradas.'),t('收入 $50 · 手艺 +1','$50 · Craft +1','$50 · Ofício +1'))},
 {t:t('把店里的桶装水涨价卖','Sell your bottled water at a markup','Vender a tua água engarrafada mais cara'),fx:()=>{S.cash+=60;S.wk.rev+=60;S.rep-=2},next:()=>say('',t('你赚了 $60。第二天主街上有人管你叫“水贩子”。这个外号跟了你两个星期。','You make $60. Next day somebody on Main Street calls you "the water man." The nickname sticks for two weeks.','Ganhas $60. No dia seguinte, alguém na rua principal chama-te «o aguadeiro». A alcunha dura duas semanas.'),t('收入 $60 · 口碑 −2','$60 · Reputation −2','$60 · Reputação −2'))}]}}},
/* W9 · graduation */
{id:'p1_grad',when:AT(9,6,0),run:()=>{const ds=M('p1_deshawn');return {title:t('高中毕业典礼','Graduation day','A cerimónia de fim de curso'),meta:t('第 9 周 · 高中橄榄球场','Week 9 · the high-school stadium','Semana 9 · o estádio do liceu'),text:[
 t('全镇都来了橄榄球场。一百二十个毕业生，学士帽在热风里乱飞。汤米和小戴尔还差一年，坐在看台上起哄。艾琳·卡斯韦尔坐在第一排，每念到一个名字都小声说：“我教过。”','The whole town is at the football stadium. A hundred and twenty graduates, mortarboards flapping in the hot wind. Tommy and Little Dale still have a year to go; they heckle from the bleachers. Irene Caswell sits in the front row and whispers "I taught that one" at every name.','A vila inteira está no estádio. Cento e vinte finalistas, os barretes a esvoaçar ao vento quente. O Tommy e o Dale filho ainda têm mais um ano; fazem barulho nas bancadas. A Irene Caswell está na primeira fila e murmura «fui professora desse» a cada nome.'),
 t(ds?'念到“德肖恩·米勒”的时候，看台上没有人喊。他的妈妈在韦科上班。他往看台上看了一眼，看见了你。':'有一个叫“德肖恩·米勒”的男孩上台时，看台上没人喊他的名字。',ds?'When they call "DeShawn Miller," nobody in the stands yells. His mom is on shift in Waco. He glances up at the bleachers and sees you.':'When a boy called "DeShawn Miller" crosses the stage, nobody in the stands yells his name.',ds?'Quando chamam «DeShawn Miller», ninguém grita nas bancadas. A mãe está a trabalhar em Waco. Ele olha para as bancadas e vê-te.':'Quando um rapaz chamado «DeShawn Miller» sobe ao palco, ninguém grita o nome dele nas bancadas.')],choices:[
 {t:t('站起来，用最大的声音喊他的名字','Stand up and yell his name as loud as you can','Levantar-te e gritar o nome dele o mais alto que puderes'),fx:()=>{MEET('p1_deshawn');addLike('p1_deshawn',3);addTrust('p1_deshawn',1);stat('tex',2)},next:()=>say('',t('你的口音把“德肖恩”喊成了三个音节。全场都笑了，然后汤米和小戴尔跟着你喊，再然后半个看台都在喊。他在台上低下头，笑得肩膀发抖。','Your accent turns "DeShawn" into three syllables. The whole stadium laughs; then Tommy and Little Dale join in, then half the bleachers. On stage he ducks his head, shoulders shaking with laughter.','O teu sotaque transforma «DeShawn» em três sílabas. O estádio inteiro ri-se; depois o Tommy e o Dale filho gritam contigo, e depois meia bancada. No palco, ele baixa a cabeça, a tremer de riso.'),t('德肖恩好感 +3 · 德州味 +2','DeShawn affection +3 · Texanness +2','Afeto do DeShawn +3 · Texanidade +2'))},
 {t:t('给毕业派对供一桌烤肉','Cater a spread for the graduation party','Fornecer uma mesa de grelhados para a festa de fim de curso'),req:()=>S.inv.pork>=6||NEED(t('库存猪肉 6','6 pork in stock','6 de porco em stock')),fx:()=>{S.inv.pork-=6;S.cash+=150;S.wk.rev+=150;S.rep+=2;addLike('p1_irene',1)},next:()=>say('',t('派对上，一百二十个十八岁的孩子第一次吃到葡式猪排包。至少二十个人发了照片。线上评分的那个数字跳了一下。','At the party, a hundred and twenty eighteen-year-olds eat their first pork cutlet sandwich. At least twenty post photos. That online number jumps.','Na festa, cento e vinte miúdos de dezoito anos comem a primeira bifana da vida. Pelo menos vinte publicam fotografias. O número da avaliação online dá um salto.'),t('收入 $150 · 口碑 +2','$150 · Reputation +2','$150 · Reputação +2'))},
 {t:t('在看台上安静地坐着','Sit quietly in the bleachers','Ficar sentado em silêncio na bancada'),fx:()=>{stat('saud',3)},next:()=>say('',t('你想起自己在里斯本的毕业典礼。妈妈坐在第三排，鲁伊在玩游戏机。你记得他们坐在哪儿，却不记得那天是谁在台上讲话。','You think of your own graduation in Lisbon. Mom in the third row, Rui on his handheld. You remember exactly where they sat, and not a word of who spoke that day.','Lembras-te do teu fim de curso em Lisboa. A mãe na terceira fila, o Rui a jogar na consola. Lembras-te exatamente de onde estavam sentados e de nada do que se disse no palco.'),t('乡愁 +3','Homesickness +3','Saudade +3'))}]}}},
/* W16 · county fair */
{id:'p1_fair',when:AT(16,2,1),run:()=>{MEET('p1_ruthann');return {title:t('县集市评比','Judging day at the county fair','Dia de concurso na feira do condado'),meta:t('第 16 周 · 县集市','Week 16 · the county fair','Semana 16 · a feira do condado'),text:[
 t('秋天的县集市：猪在叫，彩票在转，评比棚里摆满了派。评委席上坐着艾琳·卡斯韦尔，拿着一把塑料叉子，像拿着一支红笔。','The fall county fair: hogs squealing, raffle wheels spinning, the judging shed lined with pies. At the judges\' table sits Irene Caswell, holding a plastic fork like a red pen.','A feira de outono do condado: porcos a guinchar, rodas da sorte a girar, o pavilhão do concurso cheio de tartes. À mesa do júri está a Irene Caswell, de garfo de plástico na mão como quem segura uma caneta vermelha.'),
 t('露丝·安的山核桃派拿了七年蓝绶带。她冲你的蛋挞扬了扬下巴：“小家伙，敢不敢？”'+(S.flags.p1_dsFair?'隔壁青少年烧烤赛的烟里，德肖恩正在翻他的牛胸肉。':''),'Ruth Ann\'s pecan pie has taken the blue ribbon seven years running. She jerks her chin at your custard tarts. "Well, sugar? You game?"'+(S.flags.p1_dsFair?' In the smoke of the youth barbecue next door, DeShawn is turning his brisket.':''),'A tarte de noz-pecã da Ruth Ann ganha a fita azul há sete anos seguidos. Aponta com o queixo para os teus pastéis de nata. «Então, querido? Alinhas?»'+(S.flags.p1_dsFair?' No fumo do concurso de churrasco juvenil ao lado, o DeShawn está a virar o peito de vaca dele.':''))],choices:[
 {t:t('拿蛋挞参赛','Enter your custard tarts','Concorrer com os pastéis de nata'),req:()=>S.stats.oficio>=35||NEED(t('手艺 35','Craft 35','Ofício 35')),fx:()=>{S.rep+=3;S.online=clamp(S.online+3,0,100);addLike('p1_ruthann',1);addTrust('p1_irene',1)},next:()=>say(t('红绶带','The red ribbon','A fita vermelha'),t('你拿了第二名。艾琳在评语里写：“焦糖化完美。外国。”露丝·安把蓝绶带别在胸口，把你的红绶带别在你胸口：“明年再来。”','You take second. Irene writes on the card: "Perfect caramelization. Foreign." Ruth Ann pins the blue ribbon on herself and your red one on you. "Come back next year."','Ficas em segundo. A Irene escreve no cartão: «Caramelização perfeita. Estrangeiro.» A Ruth Ann prende a fita azul ao peito dela e a vermelha ao teu. «Volta para o ano.»'),t('口碑 +3 · 线上评分 +3','Reputation +3 · Online +3','Reputação +3 · Online +3'))},
 {t:`[${faceWord()}] `+t('去评委席边上“聊聊天”','Go "chat" by the judges\' table','Ir «conversar» para junto do júri'),req:CHARM_REQ(50),fx:()=>{flirt();S.online=clamp(S.online+2,0,100);addLike('p1_ruthann',-1)},next:()=>say('',t('艾琳脸红了，但还是给你打了第三名。“小伙子，听证会上那招，用一次就够了。”露丝·安一整天没理你。','Irene blushes, but still gives you third. "Young man, that trick from the hearing only works once." Ruth Ann doesn\'t speak to you for the rest of the day.','A Irene cora, mas dá-te o terceiro lugar na mesma. «Rapaz, o truque da audiência só funciona uma vez.» A Ruth Ann não te fala o resto do dia.'),t('线上评分 +2 · 露丝·安好感 −1','Online +2 · Ruth Ann affection −1','Online +2 · Afeto da Ruth Ann −1'))},
 {t:t('不参赛，去青少年烧烤赛那边给德肖恩加油','Skip the contest; go cheer DeShawn at the youth barbecue','Não concorrer; ir apoiar o DeShawn no churrasco juvenil'),req:()=>!!S.flags.p1_dsFair||NEED(t('德肖恩报名了烧烤赛','DeShawn entered the barbecue contest','O DeShawn inscreveu-se no concurso')),fx:()=>{addTrust('p1_deshawn',2);addLike('p1_deshawn',1);stat('tex',1);S.flags.p1_dsRibbon=1},next:()=>say('',t('他拿了第一。领奖的时候他没看评委，看着你，把绶带举起来晃了晃。玛丽索尔在人群后面点了点头。','He takes first. Accepting it, he doesn\'t look at the judges — he looks at you and waves the ribbon. Behind the crowd, Marisol nods.','Fica em primeiro. Ao receber o prémio não olha para o júri — olha para ti e abana a fita. Atrás da multidão, a Marisol acena com a cabeça.'),t('德肖恩信任 +2 · 德州味 +1','DeShawn trust +2 · Texanness +1','Confiança do DeShawn +2 · Texanidade +1'))},
 {t:t('买一块露丝·安的派，认输','Buy a slice of Ruth Ann\'s pie and concede','Comprar uma fatia da tarte da Ruth Ann e dar-te por vencido'),fx:()=>{S.cash-=5;addLike('p1_ruthann',2);stat('tex',1)},next:()=>say('',t('派好吃得让你有点生气。她看你吃完，满意地说：“德韦恩以前一次吃半个。”','The pie is so good it makes you a little angry. She watches you finish, satisfied. "Dwayne used to eat half of one at a sitting."','A tarte é tão boa que te irrita um bocadinho. Ela vê-te acabar, satisfeita. «O Dwayne comia meia de uma vez.»'),t('露丝·安好感 +2','Ruth Ann affection +2','Afeto da Ruth Ann +2'))}]}}},
/* W20 · Veterans Day */
{id:'p1_vets',when:AT(20,4,1),run:()=>{MEET('p1_ray');return {title:t('退伍军人节','Veterans Day','Dia dos Veteranos'),meta:t('第 20 周 · 法院广场','Week 20 · the courthouse square','Semana 20 · a praça do tribunal'),text:[
 t('法院广场的旗杆下，十一个老兵站成一排，最年轻的也七十岁了。雷·卡伦念名字：县里在越南、朝鲜、海湾、阿富汗死去的人。念到第三十一个，他停下来清了清嗓子，又接着念。','Under the flagpole on the courthouse square, eleven veterans stand in a row; the youngest is seventy. Ray Callan reads the names: the county\'s dead from Vietnam, Korea, the Gulf, Afghanistan. At the thirty-first he stops, clears his throat, and goes on.','Debaixo do mastro da praça do tribunal, onze veteranos em fila; o mais novo tem setenta anos. O Ray Callan lê os nomes: os mortos do condado no Vietname, na Coreia, no Golfo, no Afeganistão. No trigésimo primeiro para, pigarreia e continua.'),
 t('厄尔没来。孤星酒吧照常开门，门口挂着一面很旧的旗。','Earl isn\'t there. The Lone Star is open as usual, a very old flag hanging by the door.','O Earl não veio. O Lone Star está aberto como sempre, com uma bandeira muito velha pendurada à porta.')],choices:[
 {t:t('去酒吧把厄尔请来','Go to the bar and bring Earl','Ir ao bar buscar o Earl'),req:()=>rel('earl').trust>=4||!!S.flags.p1_earlPost||NEED(t('厄尔信任 4','Earl\'s trust 4','confiança do Earl 4')),fx:()=>{addTrust('earl',1);addLike('p1_ray',2);S.rep+=1},next:()=>say('',t('厄尔没进队列，站在广场边的树下，帽子拿在手里。念到一个名字时，他的嘴唇动了一下。雷看见了，没有停。','Earl doesn\'t join the line. He stands under a tree at the edge of the square, hat in hand. At one name his lips move. Ray sees it and doesn\'t stop.','O Earl não entra na fila. Fica debaixo de uma árvore na beira da praça, de chapéu na mão. Num dos nomes, os lábios mexem-se. O Ray vê e não para.'),t('厄尔信任 +1 · 雷好感 +2','Earl trust +1 · Ray affection +2','Confiança do Earl +1 · Afeto do Ray +2'))},
 {t:t('做五十个早餐卷饼给老兵和家属','Make fifty breakfast tacos for the vets and their families','Fazer cinquenta tacos de pequeno-almoço para os veteranos e as famílias'),req:()=>S.inv.dairy>=6||NEED(t('库存面粉蛋奶 6','6 flour, eggs & milk in stock','6 de farinha, ovos e leite em stock')),fx:()=>{S.inv.dairy-=6;S.rep+=3;addTrust('p1_ray',1)},next:()=>say('',t('雷吃了两个，说：“海军的伙食要是有这个，我能多干十年。”他拍拍你的肩：“水兵。”这是他第一次不叫你“西班牙小子”。','Ray eats two. "If the Navy had fed us this, I\'d have signed on ten more years." He claps your shoulder. "Sailor." First time he hasn\'t called you "Spanish boy."','O Ray come dois. «Se a Marinha nos desse isto, tinha ficado mais dez anos.» Dá-te uma palmada no ombro. «Marinheiro.» É a primeira vez que não te chama «rapaz espanhol».'),t('口碑 +3 · 雷信任 +1','Reputation +3 · Ray trust +1','Reputação +3 · Confiança do Ray +1'))},
 {t:t('摘下帽子，站在人群最后面','Take off your cap and stand at the very back','Tirar o boné e ficar lá atrás de tudo'),fx:()=>{stat('tex',2);stat('saud',1)},next:()=>say('',t('你想起外公，想起“圣安东尼号”，想起大海也有一张这样的名单，只是没人念。','You think of your grandfather, of the Santo António, of how the sea keeps a list like this too, and nobody reads it out.','Pensas no teu avô, no «Santo António», e em como o mar também tem uma lista assim, só que ninguém a lê em voz alta.'),t('德州味 +2 · 乡愁 +1','Texanness +2 · Homesickness +1','Texanidade +2 · Saudade +1'))}]}}},
/* W23 · Christmas lights parade */
{id:'p1_lights',when:AT(23,6,2),run:()=>({title:t('圣诞灯光游行','The Christmas lights parade','O desfile das luzes de Natal'),meta:t('第 23 周 · 主街','Week 23 · Main Street','Semana 23 · Rua principal'),text:[
 t('主街封了路。霍利斯的拖拉机缠满了彩灯，后面拖着一个用水管和铁丝扎的驯鹿。消防车、高中乐队、浸信会唱诗班，一辆接一辆。','Main Street is closed off. Hollis\'s tractor is wrapped in lights, towing a reindeer he built out of garden hose and wire. Fire truck, high-school band, Baptist choir, one after another.','A rua principal está fechada. O trator do Hollis está embrulhado em luzes e puxa uma rena feita de mangueira e arame. Carro dos bombeiros, banda do liceu, coro batista, um atrás do outro.'),
 t('霍利斯朝你喊：“若泽以前每年都在店门口挂一串灯，从来不进游行。今年你来不来？”','Hollis hollers at you. "José hung one string of lights outside the shop every year. Never once got in the parade. You in this year?"','O Hollis grita-te: «O José pendurava todos os anos um fio de luzes à porta. Nunca entrou no desfile. Este ano entras?»')],choices:[
 {t:t('用五金店的木料扎一辆“里斯本电车”花车','Build a "Lisbon tram" float out of lumber from the hardware store','Fazer um carro alegórico em forma de elétrico de Lisboa com madeira da loja de ferragens'),req:()=>S.stats.oficio>=30||S.cash>=80||NEED(t('手艺 30 或 $80','Craft 30 or $80','Ofício 30 ou $80')),fx:()=>{if(S.stats.oficio<30){S.cash-=80;S.wk.spend+=80}S.rep+=3;stat('saud',2);addTrust('p1_hollis',1)},next:()=>say(t('二十八路电车','The number 28','O 28'),t('一辆黄色的木头电车，车头写着“28”，车上坐着阿尔贝蒂娜太太和比，往两边撒蛋挞形状的饼干。孩子们追着车跑。有个小孩问这是不是公交车。也算是吧。','A yellow wooden tram with "28" on the front, Dona Albertina and Bea riding on it, tossing tart-shaped cookies to both sides. Kids chase it down the street. One asks if it\'s a bus. Close enough.','Um elétrico amarelo de madeira com «28» à frente, a Dona Albertina e a Bea lá em cima a atirar bolachas em forma de pastel de nata para os dois lados. Os miúdos correm atrás. Um pergunta se é um autocarro. Quase.'),t('口碑 +3 · 乡愁 +2','Reputation +3 · Homesickness +2','Reputação +3 · Saudade +2'))},
 {t:`[${faceWord()}] `+t('站上消防车，当一晚上“圣诞老人的帮手”','Ride the fire truck as "Santa\'s helper" for the night','Ir no carro dos bombeiros como «ajudante do Pai Natal»'),req:CHARM_REQ(50),fx:()=>{flirt();S.online=clamp(S.online+4,0,100);S.rep+=1},next:()=>say('',t('你戴着精灵帽，穿着一件太小的绿毛衣。第二天，网上出现了一张照片，配文：“圣鲁伊斯的精灵比北极的好看。”','Elf hat, a green sweater two sizes too small. Next day there\'s a photo online captioned: "San Luís elves beat the North Pole\'s."','Gorro de duende, uma camisola verde dois números abaixo. No dia seguinte há uma fotografia na internet com a legenda: «Os duendes de San Luís são mais giros do que os do Polo Norte.»'),t('线上评分 +4 · 口碑 +1','Online +4 · Reputation +1','Online +4 · Reputação +1'))},
 {t:t('像若泽一样，在店门口挂一串灯，煮热巧克力','Do as José did: one string of lights out front, and hot chocolate','Fazer como o José: um fio de luzes à porta e chocolate quente'),fx:()=>{S.rep+=1;stat('saud',2);S.lusoThisWeek=true},next:()=>say('',t('游行经过你店门口时，霍利斯的拖拉机按了三下喇叭。你举起杯子。门口的那串灯是若泽留下的，有一半不亮了。','As the parade passes, Hollis\'s tractor honks three times. You raise your mug. The lights by the door are José\'s; half of them are dead.','Quando o desfile passa à tua porta, o trator do Hollis buzina três vezes. Levantas a caneca. As luzes à porta eram do José; metade já não acende.'),t('口碑 +1 · 乡愁 +2','Reputation +1 · Homesickness +2','Reputação +1 · Saudade +2'))}]})},
/* W32 · burst pipes after the ice storm */
{id:'p1_pipes',when:AT(32,4,2),run:()=>{MEET('p1_ruthann');return {title:t('冻裂的水管','Burst pipes','Canos rebentados'),meta:t('第 32 周 · 冰暴之后','Week 32 · after the ice storm','Semana 32 · depois da tempestade de gelo'),text:[
 t('冰化了，水管却开始一根一根地裂。晚上露丝·安打来电话：“公园里有九家没水了，十九号的老瞎子屋里结了冰。”','The ice has melted, and now the pipes are splitting one after another. Ruth Ann calls at night. "Nine trailers out of water. Old blind man in nineteen\'s got ice on his floor."','O gelo derreteu e agora os canos rebentam uns atrás dos outros. A Ruth Ann liga à noite. «Nove caravanas sem água. O velho cego da dezanove tem gelo no chão.»'),
 S.flags.stormOpen===true?t('“冰暴那周你开着火让我们取暖，”她说，“我不好意思再开口。可我没别人可找了。”','"You kept your fire going for us the week of the storm," she says. "I hate to ask again. But I got nobody else."','«Na semana da tempestade mantiveste o lume aceso para nós», diz ela. «Custa-me pedir outra vez. Mas não tenho mais ninguém.»'):t('“冰暴那周我们挤在会所里烧旧家具，”她说，“我不怪你。可这回你能来吗？”','"The week of the storm we huddled in the veterans\' hall burning old furniture," she says. "I don\'t blame you. But could you come this time?"','«Na semana da tempestade estivemos encolhidos no posto dos veteranos a queimar móveis velhos», diz ela. «Não te culpo. Mas desta vez podes vir?»')],choices:[
 {t:t('去五金店买零件，连夜去修 $40','Buy parts at the hardware store and fix them overnight: $40','Comprar peças na loja de ferragens e arranjar tudo durante a noite: $40'),req:MONEY(40),fx:()=>{S.cash-=40;S.wk.spend+=40;S.flags.p1_pipes=1;addTrust('p1_ruthann',2);addTrust('p1_hollis',1);stat('tex',2)},next:()=>say('',t('霍利斯穿着睡衣给你开了店门，还跟着来了。你们俩趴在拖车底下修到凌晨三点。他一边拧扳手一边骂天气，用的是你教他的葡语。','Hollis opens the store in his pajamas and comes along. The two of you lie under trailers till three in the morning. He cusses the weather as he turns the wrench — in the Portuguese you taught him.','O Hollis abre a loja de pijama e vem contigo. Ficam os dois deitados debaixo das caravanas até às três da manhã. Ele pragueja contra o tempo enquanto aperta a chave — no português que lhe ensinaste.'),t('露丝·安信任 +2 · 霍利斯信任 +1 · 德州味 +2','Ruth Ann trust +2 · Hollis trust +1 · Texanness +2','Confiança da Ruth Ann +2 · Confiança do Hollis +1 · Texanidade +2'))},
 {t:t('付钱让德肖恩带人去修','Pay DeShawn to round up a crew and fix them','Pagar ao DeShawn para juntar uma equipa e arranjar'),req:()=>(M('p1_deshawn')&&S.cash>=60)||NEED(t('认识德肖恩，且有 $60','Know DeShawn, and $60','Conhecer o DeShawn e ter $60')),fx:()=>{S.cash-=60;S.wk.spend+=60;S.flags.p1_pipes=1;addTrust('p1_ruthann',1);addTrust('p1_deshawn',1)},next:()=>say('',t('德肖恩叫来了两个同学。第二天早上，九家都有了水。露丝·安给他们每人烤了一个山核桃派。','DeShawn brings two classmates. By morning all nine trailers have water. Ruth Ann bakes each of them a pecan pie.','O DeShawn traz dois colegas. De manhã, as nove caravanas têm água. A Ruth Ann faz uma tarte de noz-pecã a cada um.'),t('露丝·安信任 +1 · 德肖恩信任 +1','Ruth Ann trust +1 · DeShawn trust +1','Confiança da Ruth Ann +1 · Confiança do DeShawn +1'))},
 {t:t('把十九号的老人接到店里楼上住几天','Bring the old man from nineteen to stay upstairs at the shop for a few days','Trazer o velho da dezanove para ficar uns dias lá em cima no restaurante'),fx:()=>{S.flags.p1_pipes=1;addLike('p1_ruthann',2);S.rep+=2;stat('saud',-2)},next:()=>say('',t('他叫埃尔默，八十六岁，看不见，但能听出你哪天想家。“今天你切菜切得慢，”他说，“想你妈妈了。”他说对了。','His name is Elmer. Eighty-six, blind, and he can hear which days you\'re homesick. "You\'re chopping slow today," he says. "Missing your mama." He\'s right.','Chama-se Elmer. Oitenta e seis anos, cego, e consegue ouvir os dias em que tens saudades. «Hoje estás a cortar devagar», diz ele. «Tens saudades da tua mãe.» Tem razão.'),t('露丝·安好感 +2 · 口碑 +2','Ruth Ann affection +2 · Reputation +2','Afeto da Ruth Ann +2 · Reputação +2'))}]}}},
/* W37 · Lenten fish fry */
{id:'p1_fishfry',when:AT(37,5,2),run:()=>({title:t('大斋期的星期五','A Friday in Lent','Uma sexta-feira da Quaresma'),meta:t('第 37 周 · 教堂与会所','Week 37 · church and veterans\' hall','Semana 37 · igreja e posto de veteranos'),text:[
 t('大斋期的星期五不吃肉。圣安东尼教堂的地下室和退伍军人会所同一个晚上办炸鱼，两边都来找你。','No meat on Fridays in Lent. The basement of St. Anthony\'s and the veterans\' hall are both holding fish fries the same night, and both come asking for you.','Às sextas da Quaresma não se come carne. A cave da igreja de Santo António e o posto de veteranos fazem fritada de peixe na mesma noite, e ambos te vêm pedir ajuda.'),
 t('阿尔贝蒂娜太太说：“我们是葡萄牙人的教堂。”雷说：“我们先问的。”两个人在你店门口吵了十分钟，最后一起要了一杯咖啡。','Dona Albertina says, "We\'re the Portuguese church." Ray says, "We asked first." They argue outside your shop for ten minutes, then order one coffee together.','A Dona Albertina diz: «Nós somos a igreja dos portugueses.» O Ray diz: «Nós pedimos primeiro.» Discutem dez minutos à porta do restaurante e acabam a pedir um café juntos.')],choices:[
 {t:t('两边跑：先教堂，后会所','Do both: church first, then the hall','Fazer as duas: primeiro a igreja, depois o posto'),req:()=>(S.inv.fish>=10&&S.stats.tex>=40)||NEED(t('库存沙丁鱼 10，德州味 40','10 sardines in stock, Texanness 40','10 de sardinha em stock, Texanidade 40')),fx:()=>{S.inv.fish-=10;S.cash+=200;S.wk.rev+=200;S.rep+=4;addLike('albertina',1);addLike('p1_ray',1);S.energy=Math.max(0,S.energy-2)},next:()=>say('',t('你开着车在两边之间来回跑了四趟，身上的炭味能熏一整条街。半夜，阿尔贝蒂娜和雷在会所门口分最后一盘沙丁鱼。','You run back and forth four times between the two; you smell like enough charcoal to smoke a whole street. At midnight Albertina and Ray split the last plate of sardines outside the hall.','Fazes quatro viagens entre um sítio e o outro; cheiras a carvão que chegava para defumar uma rua. À meia-noite, a Albertina e o Ray dividem o último prato de sardinhas à porta do posto.'),t('收入 $200 · 口碑 +4 · 精力 −2','$200 · Reputation +4 · Energy −2','$200 · Reputação +4 · Energia −2'))},
 {t:t('去教堂地下室','Go to the church basement','Ir para a cave da igreja'),req:()=>S.inv.fish>=5||NEED(t('库存沙丁鱼 5','5 sardines in stock','5 de sardinha em stock')),fx:()=>{S.inv.fish-=5;S.cash+=90;S.wk.rev+=90;addLike('albertina',2);S.lusoThisWeek=true},next:()=>say('',t('九位亚速尔老太太用葡语指挥你，每个人的指令都不一样。烤到第三盘，她们终于同意了一件事：你翻鱼翻得太早。','Nine Azorean ladies direct you in Portuguese, each with different instructions. By the third tray they finally agree on one thing: you flip the fish too soon.','Nove senhoras açorianas dão-te ordens em português, cada uma diferente. À terceira travessa, finalmente concordam numa coisa: viras o peixe cedo demais.'),t('收入 $90 · 阿尔贝蒂娜好感 +2','$90 · Albertina affection +2','$90 · Afeto da Albertina +2'))},
 {t:t('去退伍军人会所','Go to the veterans\' hall','Ir para o posto de veteranos'),fx:()=>{S.cash+=60;S.wk.rev+=60;addLike('p1_ray',2);stat('tex',1)},next:()=>say('',t('雷不能碰油锅了，就坐在锅边当监工。“火太大。”“太小。”“行了。”他每说一句，就有一个老兵在旁边点头，像在听命令。','Ray can\'t touch a fryer anymore, so he sits next to it and supervises. "Too hot." "Too low." "That\'ll do." Every time he speaks, some old vet nearby nods like it\'s an order.','O Ray já não pode tocar na fritadeira, por isso fica ao lado a supervisionar. «Lume alto demais.» «Baixo demais.» «Assim está bem.» Sempre que fala, há um veterano ao lado que acena como se fosse uma ordem.'),t('收入 $60 · 雷好感 +2','$60 · Ray affection +2','$60 · Afeto do Ray +2'))}]})},
/* W38 · tornado warning */
{id:'p1_tornado',when:AT(38,7,2),run:()=>({title:t('龙卷风警报','Tornado warning','Alerta de tornado'),meta:t('第 38 周 · 星期日夜里','Week 38 · Sunday night','Semana 38 · domingo à noite'),text:[
 t('晚上九点，全镇的警报器同时响了。天是绿色的，绿得像一块坏掉的玉。收音机里说：漏斗云在县西边落地，往东北方向移动。','At nine p.m. every siren in town goes off at once. The sky is green, green like a spoiled piece of jade. The radio says a funnel has touched down in the west of the county, heading northeast.','Às nove da noite, todas as sirenes da vila tocam ao mesmo tempo. O céu está verde, verde como jade estragado. A rádio diz que um funil tocou o chão no oeste do condado e segue para nordeste.'),
 t('厄尔在电话里吼：“拖车是龙卷风最爱吃的东西！”你想起蓝帽子花公园那三十一辆拖车。','Earl bellows down the phone: "Trailers are a twister\'s favorite snack!" You think of the thirty-one trailers at the Bluebonnet.','O Earl grita-te ao telefone: «As caravanas são o petisco preferido dos tornados!» Pensas nas trinta e uma caravanas do Bluebonnet.')],choices:[
 {t:t('开皮卡去拖车公园接人','Drive the pickup to the trailer park and bring people out','Ir de carrinha ao parque de caravanas buscar as pessoas'),req:()=>canDrive()||NEED(t('有皮卡并学会开车','Own a pickup and know how to drive','Ter carrinha e saber conduzir')),fx:()=>{S.rep+=4;if(M('p1_ruthann'))addTrust('p1_ruthann',2);if(M('p1_ray'))addTrust('p1_ray',1);stat('tex',2)},next:()=>say(t('三趟','Three runs','Três viagens'),t('你跑了三趟，车斗里坐满了穿睡衣的老人和抱着狗的孩子。雷坐在副驾上，用海军的口令指挥大家低头。你们挤在店里的冷库里，听着外面的风像火车一样开过去。','Three runs, the truck bed full of old folks in pajamas and kids clutching dogs. Ray rides shotgun, barking Navy orders to keep heads down. You all cram into the shop\'s walk-in cooler and listen to the wind go by outside like a freight train.','Três viagens, a caixa da carrinha cheia de velhos de pijama e miúdos agarrados aos cães. O Ray vai ao lado a dar ordens da Marinha para baixarem a cabeça. Ficam todos enfiados na câmara frigorífica do restaurante a ouvir o vento passar lá fora como um comboio.'),t('口碑 +4 · 露丝·安信任 +2 · 德州味 +2','Reputation +4 · Ruth Ann trust +2 · Texanness +2','Reputação +4 · Confiança da Ruth Ann +2 · Texanidade +2'))},
 {t:t('打开店门，让主街上的人进冷库躲','Open the shop and let Main Street shelter in the walk-in','Abrir o restaurante e deixar a rua principal abrigar-se na câmara frigorífica'),fx:()=>{S.rep+=2;stat('saud',-1);if(M('p1_hollis'))addLike('p1_hollis',1)},next:()=>say('',t('冷库里挤了十四个人，霍利斯、比、两个卡车司机、一只猫。有人开始唱赞美诗，有人跟着唱，比用葡语唱了外婆的调子。外面安静下来的时候，没人急着出去。','Fourteen people in the walk-in: Hollis, Bea, two truckers, a cat. Somebody starts a hymn, others join, and Bea hums her grandma\'s tune in Portuguese. When it goes quiet outside, nobody\'s in a hurry to leave.','Catorze pessoas na câmara frigorífica: o Hollis, a Bea, dois camionistas, um gato. Alguém começa um hino, outros acompanham, e a Bea cantarola a moda da avó. Quando lá fora fica tudo calmo, ninguém tem pressa de sair.'),t('口碑 +2','Reputation +2','Reputação +2'))},
 {t:t('一个人躲进冷库，给妈妈打电话','Hide in the walk-in alone and call your mother','Esconder-te sozinho na câmara frigorífica e ligar à tua mãe'),fx:()=>{stat('saud',4)},next:()=>say('',t('里斯本是凌晨三点。她接了，没问为什么，只是说：“我在。”你们谁也没说话，听了二十分钟彼此的呼吸。早上你才知道，龙卷风刮走了邓巴五金店的招牌，别的什么都没碰。','It\'s three a.m. in Lisbon. She answers and doesn\'t ask why. Just: "I\'m here." Neither of you speaks; you listen to each other breathe for twenty minutes. In the morning you learn the twister took Dunbar Hardware\'s sign and touched nothing else.','Em Lisboa são três da manhã. Ela atende e não pergunta porquê. Só: «Estou aqui.» Nenhum dos dois fala; ficam vinte minutos a ouvir a respiração um do outro. De manhã sabes que o tornado levou a tabuleta da loja Dunbar e não tocou em mais nada.'),t('乡愁 +4','Homesickness +4','Saudade +4'))}]})},
/* W39 · before the council vote */
{id:'p1_precouncil',when:()=>S.week===39&&S.day===4&&S.slot===1&&!!(S.flags.p1_councilVote||S.flags.p1_ruthWitness||S.flags.p1_clipping),run:()=>{
 const lines=[];
 if(S.flags.p1_councilVote)lines.push(t('霍利斯在五金店门口拦住你，往你手里塞了一颗薄荷糖：“今晚我投反对。别看我，看前面。”','Hollis stops you outside the hardware store and presses a mint into your hand. "I\'m voting no tonight. Don\'t look at me. Look straight ahead."','O Hollis trava-te à porta da loja e mete-te uma pastilha de mentol na mão. «Esta noite voto contra. Não olhes para mim. Olha em frente.»'));
 if(S.flags.p1_ruthWitness)lines.push(t('露丝·安穿着一条新裙子，标签还没剪。她把 1999 年的信叠了又叠：“我念的时候要是抖，你别看我。”','Ruth Ann is in a new dress, tag still on. She folds the 1999 letter over and over. "If I shake when I read it, don\'t look at me."','A Ruth Ann tem um vestido novo, ainda com a etiqueta. Dobra e redobra a carta de 1999. «Se eu tremer a ler, não olhes para mim.»'));
 if(S.flags.p1_clipping)lines.push(t('艾琳把那张 1997 年的剪报放大复印了五份，一位议员一份。“历史老师的老毛病，”她说，“开会前先发讲义。”','Irene has blown up the 1997 clipping and made five copies, one per councilmember. "Old history-teacher habit," she says. "Hand out the reading before class."','A Irene ampliou o recorte de 1997 e fez cinco cópias, uma por vereador. «Mania de professora de história», diz ela. «Distribuir os apontamentos antes da aula.»'));
 return {title:t('投票前的下午','The afternoon before the vote','A tarde antes da votação'),meta:t('第 39 周 · 镇议会今晚开会','Week 39 · council meets tonight','Semana 39 · a câmara reúne esta noite'),text:[t('离议会开会还有几个小时。镇上的人一个接一个来找你。','A few hours before the council meets. One by one, people from town come to find you.','Faltam umas horas para a reunião da câmara. Uma a uma, pessoas da vila vêm ter contigo.'),...lines],choices:[
  {t:t('谢谢他们每一个人','Thank every one of them','Agradecer a cada um'),fx:()=>{if(S.flags.p1_ruthWitness&&!S.flags.c4_witness)S.flags.c4_witness='p1_ruthann';S.rep+=1;stat('tex',1)},next:()=>say('',t('你忽然明白，若泽二十年没敢开口，是因为他以为自己是一个人。','It hits you: José kept quiet for twenty years because he thought he was alone.','De repente percebes: o José calou-se vinte anos porque pensava que estava sozinho.'))},
  {t:t('请他们别为你冒险','Ask them not to take risks for you','Pedir-lhes que não se arrisquem por ti'),fx:()=>{if(S.flags.p1_ruthWitness&&!S.flags.c4_witness)S.flags.c4_witness='p1_ruthann';stat('saud',2)},next:()=>say('',t('霍利斯笑了：“孩子，这不是为你。这是我们的镇子。”','Hollis laughs. "Son, this ain\'t for you. It\'s our town."','O Hollis ri-se. «Rapaz, isto não é por ti. A terra é nossa.»'))}]}}},
/* W46 · marchas rehearsal — the townsfolk join the festival */
{id:'p1_marchas',when:AT(46,1,1),run:()=>{
 const c=S.flags.p1_crew||[],L=[];
 if(c.indexOf('irene')>=0)L.push(t('艾琳举着 1979 年的横幅，她以前的学生在后面排成两行，有人拄着拐杖。','Irene carries the 1979 banner, her former students in two rows behind her, one on a cane.','A Irene leva a faixa de 1979, os antigos alunos em duas filas atrás dela, um de bengala.'));
 if(c.indexOf('ray')>=0)L.push(t('雷的仪仗队走在最前面：九个老兵，两面旗，雷坐在轮椅上，喊口令喊得比谁都响。','Ray\'s color guard out front: nine old vets, two flags, Ray in a wheelchair calling cadence louder than anyone.','A guarda de honra do Ray à frente: nove veteranos, duas bandeiras, o Ray de cadeira de rodas a marcar o passo mais alto do que todos.'));
 if(c.indexOf('deshawn')>=0)L.push(t('德肖恩在店后支起了第二个烤架，用他的新刀切柠檬，切得比你整齐。','Out back DeShawn has set up the second grill and is slicing lemons with his new knives, neater than you.','Nas traseiras, o DeShawn montou a segunda grelha e corta limões com as facas novas, mais certinhos do que tu.'));
 if(c.indexOf('bea')>=0)L.push(t('比把“亚速尔角”搬到了图书馆门口的台阶上，外婆的照片用晾衣夹夹在一根绳子上。','Bea has moved the Azores corner onto the library steps, Grandma\'s photos clothespinned to a line.','A Bea levou o cantinho dos Açores para os degraus da biblioteca, com as fotografias da avó presas com molas a um fio.'));
 if(M('p1_ruthann')&&ST('ruthann')>=2)L.push(t('露丝·安带着拖车公园的女人们在剪纸花，剪了四百朵，“德韦恩说过，做事要做过头”。','Ruth Ann and the trailer-park women are cutting paper flowers — four hundred of them. "Dwayne always said, if you\'re gonna do it, overdo it."','A Ruth Ann e as mulheres do parque estão a recortar flores de papel — quatrocentas. «O Dwayne dizia sempre: se é para fazer, é para exagerar.»'));
 const n=L.length,add=Math.min(3,Math.round(n*0.6));
 if(!n)return {title:t('游行彩排','Parade rehearsal','Ensaio do desfile'),meta:t('第 46 周 · 主街','Week 46 · Main Street','Semana 46 · Rua principal'),text:[t('高中乐队在主街上彩排游行。乐手比观众多。霍利斯在五金店门口看着：“若泽那年也是这样，人不够。”','The high-school band rehearses the parade on Main Street. More musicians than spectators. Hollis watches from the hardware store. "Same as José\'s year. Not enough folks."','A banda do liceu ensaia o desfile na rua principal. Mais músicos do que público. O Hollis observa da porta da loja. «Igual ao ano do José. Pouca gente.»')],choices:[
  {t:t('走到主街上，一家一家去敲门','Walk Main Street and knock on every door','Percorrer a rua principal e bater a todas as portas'),req:()=>S.rep>=35||NEED(t('口碑 35','Reputation 35','Reputação 35')),fx:()=>{fest(1,'p1_town');S.flags.p1_festHelp=1;stat('tex',1)},next:()=>say('',t('敲了三十扇门，有七家说来。七家也是人。','Thirty doors. Seven say they\'ll come. Seven is people.','Trinta portas. Sete dizem que vêm. Sete já é gente.'),t('节日筹备 +1','Festival prep +1','Preparação da festa +1'))},
  {t:t('站在路边给乐队鼓掌','Stand at the curb and applaud the band','Ficar no passeio a aplaudir a banda'),fx:()=>stat('saud',2)}]};
 return {title:t('游行彩排','Parade rehearsal','Ensaio do desfile'),meta:t(`第 46 周 · 主街 · 镇上来帮忙的：${n}`,`Week 46 · Main Street · townsfolk pitching in: ${n}`,`Semana 46 · Rua principal · gente da vila a ajudar: ${n}`),text:[
  t('高中乐队在主街上彩排游行。他们自己选的那首歌果然很难听。可这一次，乐队后面跟着人。','The high-school band rehearses the parade on Main Street. The song they chose themselves is every bit as awful as promised. But this time, people are following the band.','A banda do liceu ensaia o desfile na rua principal. A canção que escolheram é tão horrível como se previa. Mas desta vez há gente atrás da banda.'),...L,
  t('霍利斯站在没有招牌的五金店门口，摘下帽子：“1979 年以后，这条街第一次这么挤。”','Hollis stands outside his signless hardware store, hat off. "First time this street\'s been this crowded since 1979."','O Hollis, à porta da loja sem tabuleta, tira o chapéu. «Desde 1979 que esta rua não estava tão cheia.»')],choices:[
  {t:t('加入队伍，从主街这头走到那头','Fall in and march from one end of Main Street to the other','Entrar no cortejo e percorrer a rua principal de ponta a ponta'),fx:()=>{fest(add,'p1_town');S.flags.p1_festHelp=1;S.rep+=2;stat('saud',-2);log(`镇民加入圣安东尼节，节日筹备 +${add}`,`The townsfolk join Santo António: festival prep +${add}`,`A gente da vila junta-se ao Santo António: preparação da festa +${add}`)},next:()=>say('',t('走到街尾你回头看，队伍比你想的长。若泽列的那张名单上的人，你一个电话都没打，他们自己来了。','At the end of the street you look back; the line is longer than you thought. The people on José\'s list — you never made a single call, and they came on their own.','No fim da rua olhas para trás; o cortejo é maior do que pensavas. A gente da lista do José — não fizeste um único telefonema, e vieram por si.'),t(`节日筹备 +${add}`,`Festival prep +${add}`,`Preparação da festa +${add}`))}]};
}}
);

